∀ {Owner Workload Evidence BaseState ExtendedState : Type} {owner : Workload → Owner}
  {independentOwners : Owner → Owner → Prop}
  {authorizedPolicy :
    (Owner → Owner → Prop) →
      (Workload → Prop) →
        (Workload → Prop) →
          SearchRouteEvidenceGraphAdmission.RouteCost → SearchRouteEvidenceGraphAdmission.SharedComplexity → Prop}
  {evidenceVerifier : Workload → SearchRouteEvidenceGraphAdmission.MeasurementContext → List Evidence → Prop}
  {authorizedVerifier : (Workload → SearchRouteEvidenceGraphAdmission.MeasurementContext → List Evidence → Prop) → Prop}
  {admittedWorkload affected measuredWorkload : Workload → Prop}
  {baseline extended : Workload → SearchRouteEvidenceGraphAdmission.EvidenceRoute Evidence}
  {externalityBudget : SearchRouteEvidenceGraphAdmission.RouteCost}
  {complexityBudget complexityDelta : SearchRouteEvidenceGraphAdmission.SharedComplexity}
  (certificate :
    SearchRouteEvidenceGraphAdmission.CoreAdmissionCertificate Owner Workload Evidence BaseState ExtendedState owner
      independentOwners authorizedPolicy evidenceVerifier authorizedVerifier admittedWorkload affected measuredWorkload
      baseline extended externalityBudget complexityBudget complexityDelta),
  SearchRouteEvidenceGraphAdmission.IndependentValue owner independentOwners admittedWorkload baseline extended

∀ {Owner Workload Evidence BaseState ExtendedState : Type} {owner : Workload → Owner}
  {independentOwners : Owner → Owner → Prop}
  {authorizedPolicy :
    (Owner → Owner → Prop) →
      (Workload → Prop) →
        (Workload → Prop) →
          SearchRouteEvidenceGraphAdmission.RouteCost → SearchRouteEvidenceGraphAdmission.SharedComplexity → Prop}
  {evidenceVerifier : Workload → SearchRouteEvidenceGraphAdmission.MeasurementContext → List Evidence → Prop}
  {authorizedVerifier : (Workload → SearchRouteEvidenceGraphAdmission.MeasurementContext → List Evidence → Prop) → Prop}
  {admittedWorkload affected measuredWorkload : Workload → Prop}
  {baseline extended : Workload → SearchRouteEvidenceGraphAdmission.EvidenceRoute Evidence}
  {externalityBudget : SearchRouteEvidenceGraphAdmission.RouteCost}
  {complexityBudget complexityDelta : SearchRouteEvidenceGraphAdmission.SharedComplexity}
  (certificate :
    SearchRouteEvidenceGraphAdmission.CoreAdmissionCertificate Owner Workload Evidence BaseState ExtendedState owner
      independentOwners authorizedPolicy evidenceVerifier authorizedVerifier admittedWorkload affected measuredWorkload
      baseline extended externalityBudget complexityBudget complexityDelta),
  ∃ left right,
    admittedWorkload left ∧
      admittedWorkload right ∧
        owner left ≠ owner right ∧
          SearchRouteEvidenceGraphAdmission.CertifiedImprovement (baseline left) (extended left) ∧
            SearchRouteEvidenceGraphAdmission.CertifiedImprovement (baseline right) (extended right)

