∀ {Owner Workload Evidence BaseState ExtendedState : Type} {owner : Workload → Owner}
  {independentOwners : Owner → Owner → Prop}
  {authorizedPolicy :
    (Owner → Owner → Prop) →
      (Workload → Prop) →
        (Workload → Prop) →
          SearchRouteEvidenceGraphAdmission.RouteCost → SearchRouteEvidenceGraphAdmission.SharedComplexity → Prop}
  {evidenceVerifier : Workload → SearchRouteEvidenceGraphAdmission.MeasurementContext → List Evidence → Prop}
  {authorizedVerifier : (Workload → SearchRouteEvidenceGraphAdmission.MeasurementContext → List Evidence → Prop) → Prop}
  {admittedWorkload affected measuredWorkload : Workload → Prop}
